void *scheduler(void *arg) {                 /* runs in its own thread */
    ao_t *ao = arg;
    while (!ao->stop) {
        req_t *r = queue_pop(&ao->q);        /* blocks on the condition variable */
        if (r) { r->call(r); r->publish(r); } /* only this thread touches the servant */
    }
    return NULL;
}
